<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Http\Requests\CategoryRequest; use App\Http\Resources\CategoryResource; use App\Models\Category; use Illuminate\Http\JsonResponse; use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
class CategoryController extends Controller { public function index(): AnonymousResourceCollection { return CategoryResource::collection(Category::withCount('products')->orderBy('name')->get()); } public function store(CategoryRequest $r): JsonResponse { return response()->json(['data'=>new CategoryResource(Category::create($r->validated()))],201); } public function show(Category $category): CategoryResource { return new CategoryResource($category->loadCount('products')); } public function update(CategoryRequest $r,Category $category): CategoryResource { $category->update($r->validated()); return new CategoryResource($category); } public function destroy(Category $category): JsonResponse { if($category->products()->exists()) return response()->json(['message'=>'A category with products cannot be deleted.'],422); $category->delete(); return response()->json(null,204); } }
